def read(p):return p.read_bytes().decode('utf-8')
def require(x,message):
 if not x:raise ValueError(message)
def soup_of(text):return BeautifulSoup(text,'lxml')
def visible(s):
 for t in s.body.find_all(string=True):
  if isinstance(t,(Comment,Doctype)) or any(p.name in ['script','style','template'] for p in t.parents):continue
  yield t

def protected(t):
 return any(p.name in ['script','style','blockquote'] or p.get('lang') in ['ja','en'] or p.has_attr('data-official-name') or p.has_attr('data-v10-official-name') for p in t.parents if p.name not in ['html','body'])

def bed_text(text,lang):
 i=1 if lang=='ko' else 0
 result=text
 for key,labels in sorted(BEDS.items(),key=lambda kv:-len(kv[0])):
  result=re.sub(r'\b'+re.escape(key)+r's?\b',labels[i],result,flags=re.I)
 labels=sorted({v[i] for v in BEDS.values()},key=len,reverse=True)
 pat=r'(\d+)\s+('+'|'.join(map(re.escape,labels))+r')'
 result=re.sub(pat,lambda m:f'{m[2]} {m[1]}개' if lang=='ko' else f'{m[1]}張{m[2]}',result)
 if lang=='zh-tw':
  result=re.sub(r'\s*[,、]\s*','、',result)
  result=re.sub(r'\s*[（(]\s*','（',result);result=re.sub(r'\s*[）)]','）',result)
 else:
  result=re.sub(r'\s*[,、]\s*',', ',result)
  result=re.sub(r'\(\s*','(',result);result=re.sub(r'\s*\)',')',result)
 return result

def bed_candidate(t,lang):
 labels=[v[1 if lang=='ko' else 0] for v in BEDS.values()]
 # Beds-only text: do not rewrite explanatory prose or room names.
 return (bool(re.match(r'^\s*\d+\s+(?:'+'|'.join(map(re.escape,labels))+r'|single|double|queen|king|semi-double|bunk|futon|sofa|daybed|loft)',t,re.I)) or bool(re.match(r'^\s*(?:上下舖|이층 침대)\s*\(',t)))

def signature(s):
 data=s.select_one('#gsj-page-data')
 return {'data':data.string if data else None,'canonical':[dict(t.attrs) for t in s.select('link[rel=canonical]')],'hreflang':[dict(t.attrs) for t in s.select('link[hreflang]')], 'links':[(a.get('href'),a.get('data-affiliate-link')) for a in s.select('a[href]')], 'scripts':[(dict(t.attrs),t.string) for t in s.find_all('script')], 'options':[(dict(o.attrs)) for o in s.select('#room-type option')], 'roomOrder':[r.get('id') for r in s.select('article.room')]}

def patch_page(text,lang,kind,slug,names,used,stats):
 s=soup_of(text);before=str(s);sig=signature(s)
 old_en_meta=(str(s.title),str(s.select_one('meta[name=description]')))
 # 1. Translate only supplied room-name keys. Unknown Japanese room names stop all writes.
 if lang in PREFIX:
  selectors='article.room h2, #room-type option, span[data-official-name], article.room .metrics .pill' if kind=='stays' else 'span[data-official-name]'
  for el in s.select(selectors):
   old=el.get_text()
   if old in names:
    used.add(old);el.string=names[old];stats['roomNames']+=1
    if el.name=='h2':
     note=s.new_tag('p',attrs={'data-v10-official-name':''});small=s.new_tag('small');small.append(PREFIX[lang]);span=s.new_tag('span',lang='ja');span.string=old;small.append(span);note.append(small);el.insert_after(note)
   elif KANA.search(old):raise ValueError(f'Unmapped room name {slug}: {old}')
   elif el.name=='h2':
    note=el.find_next_sibling('p',attrs={'data-v10-official-name':True})
    if note:
     original=note.select_one('[lang=ja]').get_text();require(names.get(original)==old,'Changed mapping for '+original);used.add(original)
  if kind=='stays':
   for p in s.select('.hero > p'):
    if p.find('span',lang='ja'):continue
    address=p.get_text()
    if address.startswith('〒'):
     p.clear();p.append(ADDRESS[lang]);span=s.new_tag('span',lang='ja');span.string=address;p.append(span);stats['addresses']+=1
 # 3. Keep exact source quotes, identify their language.
 for quote in s.find_all('blockquote'):
  source='ja' if KANA.search(quote.get_text()) else 'en'
  if source!=lang and (lang,source) in QUOTE:
   summary=quote.find_parent('details').find('summary')
   if summary.string!=QUOTE[lang,source] or quote.get('lang')!=source:stats['quoteLabels']+=1
   summary.string=QUOTE[lang,source];quote['lang']=source
 # 4/5/6/8/9: visible text only; scripts, room data and official quotes remain untouched.
 for node in list(visible(s)):
  if protected(node):continue
  original=str(node);value=original
  if lang=='en' and kind=='stays':value=re.sub(r'Average across (\d+) properties:',r'Difference from the average of \1 properties:',value)
  if kind=='stays' and node.parent.name=='li' and node.find_parent('article',class_='room') and node.find_parent('details'):
   value=re.sub(r';\s*$','',value)
  if lang in ['ko','zh-tw'] and bed_candidate(value,lang):value=bed_text(value,lang)
  if kind=='tokyo' and lang in ['ko','zh-tw','ja']:
   idx={'ko':0,'zh-tw':1,'ja':2}[lang]
   if value.strip() in PLACE:value=value.replace(value.strip(),PLACE[value.strip()][idx])
   if lang!='ja' and value.strip() in AREA:value=value.replace(value.strip(),AREA[value.strip()][idx])
   value=value.replace('42㎡ room available',{'ko':'42㎡ 객실 있음','zh-tw':'有42㎡的房型','ja':'42㎡の客室あり'}[lang])
   if lang=='zh-tw':value=value.replace('廚房・可使用洗衣設備（位置依飯店／房型）','廚房、可使用洗衣設備（位置依飯店與房型而異）')
  if lang=='ja' and ((kind=='stays' and node.find_parent('article',class_='room')) or (kind=='tokyo' and 'long-stay' in slug)):
   if node.parent.name in ['p','td']:
    value=re.sub(r'(×\d+)\s+(?=(?:布団|ソファベッド|デイベッド|シングル|ダブル|クイーン|キング|二段|セミダブル))',r'\1、',value)
  if original!=value:node.replace_with(value);stats['visibleTextNodes']+=1
 if kind=='stays' and lang in ['ko','zh-tw','ja']:
  data=META[slug];suffix={'ko':'ko','zh-tw':'zh','ja':'ja'}[lang]
  s.title.string=data['title_'+suffix]
  if data['desc_'+suffix] is not None:s.select_one('meta[name=description]')['content']=data['desc_'+suffix]
  if lang=='ja':
   s.select_one('.hero > p').string=data['header_place_ja']
   if data['excluded']:
    for p in s.select('.hero > p'):
     if p.get_text()=='Nagasaki, Japan':p.string='長崎'
 if kind=='article' and lang=='ja':
  reference=soup_of(read(ROOT/'ja/tokyo/4-guests/index.html'))
  s.footer.select_one('.small').string=reference.footer.select_one('.small').get_text()
  s.footer.select_one('.foot > a').string=reference.footer.select_one('.foot > a').get_text()
 require(signature(s)==sig,'Protected data/links/options/scripts changed: '+slug)
 if lang=='en' and kind in ['stays','tokyo']:require((str(s.title),str(s.select_one('meta[name=description]')))==old_en_meta,'English metadata changed: '+slug)
 result=str(s)
 return text if result==before else result

def build(day):
 datetime.strptime(day,'%Y-%m-%d')
 names=json.loads(read(ROOT/'config/room-names-en.json'));require(len(names)==106,'Expected 106 mapped room names')
 changes={};used=set();counts=Counter();details={}
 # Required priority: English, Korean / Traditional Chinese, Japanese.
 for lang in ['en','ko','zh-tw','ja']:
  prefix='' if lang=='en' else lang+'/'
  for f in sorted((ROOT/(prefix+'stays')).glob('*/index.html')):
   text=read(f);stats=Counter();new=patch_page(text,lang,'stays',f.parent.name,names,used,stats)
   if new!=text:changes[f]=new;counts[lang+'/stays']+=1;details[f.relative_to(ROOT).as_posix()]=dict(stats)
  for f in sorted((ROOT/(lang+'/tokyo')).glob('*/index.html')):
   text=read(f);stats=Counter();new=patch_page(text,lang,'tokyo',f.parent.name,names,used,stats)
   if new!=text:changes[f]=new;counts[lang+'/tokyo']+=1;details[f.relative_to(ROOT).as_posix()]=dict(stats)
 f=ROOT/'ja/real-beds/index.html';text=read(f);new=patch_page(text,'ja','article','real-beds',names,used,Counter())
 if new!=text:changes[f]=new;counts['ja/article']+=1
 require(used==set(names),'Unused room names: '+str(set(names)-used))
 # A previously changed page retains its date on an identical second run.
 changed_urls={'https://groupstayjapan.synthx.jp/'+f.relative_to(ROOT).as_posix().removesuffix('index.html') for f in changes}
 sitemap_changes={};lastmods=[]
 for f in ROOT.glob('sitemap*.xml'):
  original=read(f)
  def update(m):
   block=m[0];loc=re.search(r'<loc>(.*?)</loc>',block)
   if loc and loc[1] in changed_urls:
    old=re.search(r'<lastmod>(.*?)</lastmod>',block)
    require(old is not None,'Missing lastmod '+loc[1]);lastmods.append(loc[1])
    return re.sub(r'<lastmod>.*?</lastmod>',f'<lastmod>{day}</lastmod>',block)
   return block
  new=re.sub(r'<url>.*?</url>',update,original,flags=re.S)
  if new!=original:sitemap_changes[f]=new
 require(set(lastmods)==changed_urls,'Changed page missing from sitemap: '+str(changed_urls-set(lastmods)))
 changes.update(sitemap_changes)
 readme=ROOT/'README.md';text=read(readme);line='生成のあと最後に `python scripts/apply-v10.py --date YYYY-MM-DD` を実行する。'
 if line not in text:changes[readme]=text.rstrip()+'\r\n\r\n'+line+'\r\n'
 for f,new in changes.items():f.write_bytes(new.encode('utf-8'))
 print(json.dumps({'changedPages':dict(counts),'pageTotal':sum(counts.values()),'lastmodURLs':len(lastmods),'roomNameKeysUsed':len(used),'unmappedRoomNames':0,'changedFiles':len(changes)},ensure_ascii=False,indent=2))
 return details

if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--date',default=datetime.now(timezone(timedelta(hours=9))).date().isoformat());args=p.parse_args();build(args.date)
